# hypothesis: A method annotated with a forward reference to B reads an Optional[int] attribute that B.__init__ sets, and a decorator-wrapped factory keeps its declared return type.
from __future__ import annotations
from typing import Callable, Optional, TypeVar, reveal_type

T = TypeVar('T')


def deco(fn: Callable[[], T]) -> Callable[[], T]:
    def wrapper() -> T:
        return fn()
    return wrapper


class C:
    def make_b(self) -> B:
        return B()

    def peek(self, b: B) -> int | None:
        reveal_type(b._foo)
        return b._foo


class B:
    def __init__(self) -> None:
        self._foo: Optional[int] = None


@deco
def defer() -> int:
    return 3


c = C()
b = c.make_b()
print(c.peek(b))
b._foo = defer()
reveal_type(defer())
print(c.peek(b))
